- **Fact Checks:** If the text claims "Our product is 5x faster", search the web. If no info is found, mark as "Unverified" (Hallucination risk). If found, "Verified".
- **Competitors:** List 2-3 ACTUAL recent articles/posts from the web that are similar to this content.
- **Rewrites:** Must be full-length and detailed.
- **Language:** All feedback/text must be in KOREAN. Status values must be English.
`;

// Helper to clean markdown json blocks if the model ignores instructions
function cleanJsonString(text: string): string {
    let clean = text.trim();
    if (clean.startsWith('```json')) {
        clean = clean.replace(/^```json/, '').replace(/```$/, '');
    } else if (clean.startsWith('```')) {
        clean = clean.replace(/^```/, '').replace(/```$/, '');
    }
    return clean;
}

export const analyzeContent = async (text: string): Promise<AnalysisResult> => {
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: text,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        // IMPORTANT: responseSchema and responseMimeType are NOT allowed with googleSearch tool.
        // We rely on the prompt to enforce JSON structure.
        tools: [{ googleSearch: {} }], 
      }
    });

    if (!response.text) {
        throw new Error("No response generated from AI");
    }

    // 1. Parse JSON Content
    const cleanedText = cleanJsonString(response.text);
    let result: AnalysisResult;
    try {
        result = JSON.parse(cleanedText) as AnalysisResult;
    } catch (e) {
        console.error("JSON Parse Error:", e);
        console.log("Raw Text:", response.text);
        throw new Error("AI analysis response was not valid JSON.");
    }

    // 2. Extract Grounding Metadata (Real URLs)
    // The SDK returns grounding chunks in candidates[0].groundingMetadata
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const webSources = groundingChunks
        .filter((chunk: any) => chunk.web?.uri && chunk.web?.title)
        .map((chunk: any) => ({
            uri: chunk.web.uri,
            title: chunk.web.title
        }));

    // 3. Merge Grounding Data into Result
    if (result.realtime) {
        result.realtime.groundingSources = webSources;

        // Attempt to link fact checks to real sources if possible
        // (This is a heuristic, as specific mapping isn't always 1:1 in the API response)
        result.realtime.factChecks = result.realtime.factChecks.map((check, idx) => ({
            ...check,
            sourceUrl: webSources[idx % webSources.length]?.uri // Distribute sources for reference
        }));
    }

    return result;

  } catch (error) {
    console.error("AI Analysis Failed:", error);
    throw error;
  }
};

