export default App;

export enum AnalysisStatus {
  IDLE = 'IDLE',
  ANALYZING = 'ANALYZING',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR',
}

export interface Metric {
  name: string;
  score: number; // 0-100
  feedback: string;
  status: 'Good' | 'Needs Improvement' | 'Weak';
}

export interface Snippet {
  question: string;
  answer: string;
}

export interface RewriteSet {
  basic: string;
  linkedin: string;
  newsroom: string;
  faq: string;
  tldr: string;
}

// --- New Types for Grounding ---
export interface WebSource {
  uri: string;
  title: string;
}

export interface FactCheckItem {
  claim: string;
  verification: 'Verified' | 'Contradicted' | 'Unverified';
  comment: string;
  sourceUrl?: string; // Optional URL if found
}

export interface CompetitorInsight {
  title: string;
  url: string;
  sourceName: string;
}

export interface RealtimeAnalysisData {
  factChecks: FactCheckItem[];
  competitors: CompetitorInsight[];
  groundingSources: WebSource[]; // From metadata
}
// -------------------------------

export interface AnalysisResult {
  totalScore: number;
  summary: string;
  metrics: Metric[];
  snippets: Snippet[];
  rewrites: RewriteSet;
  checklists: {
    basic: string[];
    linkedin: string[];
    newsroom: string[];
    faq: string[];
    tldr: string[];
  };
  // New Optional Field for Grounding Results
  realtime?: RealtimeAnalysisData;
}

// Admin Types
export interface AnalysisLog {
  id: string;
  userEmail: string;
  inputText: string;
  resultSummary: string;
  score: number;
  date: string;
  status: 'Completed' | 'Failed';
  // Added: Store the grounding data in the log
  realtimeData?: RealtimeAnalysisData;
}

export interface AdminStats {
  totalAnalyses: number;
  activeUsers: number;
  avgScore: number;
  growthRate: number;
}

