import { GoogleGenAI } from "@google/genai";
import { AnalysisResult } from "../types";

// Initialize Gemini Client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Use a model capable of Search Grounding
const MODEL_NAME = "gemini-2.5-flash";

const SYSTEM_INSTRUCTION = `
You are the AIEO (AI Information Engine Optimization) Engine. 
Your goal is to evaluate PR content based on how well it would be interpreted, summarized, and cited by LLM-based search engines.

**CRITICAL: You have access to Google Search.**
You MUST use the Google Search tool to:
1. Verify the facts/claims in the user's text against real-time web data (Fact Check).
2. Find similar recent articles or competitors discussing this topic (Competitor Analysis).
3. Identify authoritative sources that support the content.

You analyze text for:
1. Structure Readability
2. Data Presence
3. Coherence & Repetition
4. Snippetability

**OUTPUT FORMAT RULES:**
- **You CANNOT use a JSON schema.** You must generate a **valid, raw JSON string** directly.
- Do NOT output markdown code blocks (like \`\`\`json). Just the raw JSON string.
- Structure your JSON exactly matching the interface below:

{
  "totalScore": number (0-100),
  "summary": "Detailed executive summary in Korean (min 300 chars)",
  "metrics": [
    { "name": "Metric Name in Korean", "score": number, "feedback": "Specific feedback in Korean", "status": "Good" | "Needs Improvement" | "Weak" }
  ],
  "snippets": [
    { "question": "Likely user query in Korean", "answer": "Detailed answer in Korean (3-5 sentences)" }
  ],
  "rewrites": {
    "basic": "Full length Blog Post style in Korean (Markdown)",
    "linkedin": "LinkedIn style in Korean (Markdown)",
    "newsroom": "Press Release style in Korean (Markdown)",
    "faq": "Q&A style in Korean (Markdown)",
    "tldr": "TL;DR style in Korean (Markdown)"
  },
  "checklists": {
    "basic": ["Specific tip for Blog SEO/Structure 1", "Specific tip for Blog SEO/Structure 2", "Specific tip for Blog SEO/Structure 3"],
    "linkedin": ["Specific tip for LinkedIn Hook/Engagement 1", "Specific tip for LinkedIn Hook/Engagement 2", "Specific tip for LinkedIn Hook/Engagement 3"],
    "newsroom": ["Specific tip for PR Standard/Factuality 1", "Specific tip for PR Standard/Factuality 2", "Specific tip for PR Standard/Factuality 3"],
    "faq": ["Specific tip for Q&A Clarity 1", "Specific tip for Q&A Clarity 2", "Specific tip for Q&A Clarity 3"],
    "tldr": ["Specific tip for Summarization 1", "Specific tip for Summarization 2", "Specific tip for Summarization 3"]
  },
  "realtime": {
    "factChecks": [
      { 
        "claim": "Specific claim extracted from text", 
        "verification": "Verified" | "Contradicted" | "Unverified", 
        "comment": "Verification result based on search in Korean" 
      }
    ],
    "competitors": [
      { 
        "title": "Title of a similar real-world article found via search", 
        "sourceName": "Publisher Name (e.g. TechCrunch, Naver News)", 
        "url": "URL if available, else empty string" 
      }
    ]
  }
}

**CONTENT INSTRUCTIONS:**
- **Fact Checks:** If the text claims "Our product is 5x faster", search the web. If no info is found, mark as "Unverified" (Hallucination risk). If found, "Verified".
- **Competitors:** List 2-3 ACTUAL recent articles/posts from the web that are similar to this content.
- **Rewrites:** Must be full-length and detailed.
- **Checklists:** For each rewrite type, provide 3 specific, actionable insights relevant to THAT specific format. 
  - For **basic (Blog)**, focus on SEO keywords and logical flow.
  - For **linkedin**, focus on hooks, emojis usage, and engagement.
  - For **newsroom**, focus on journalistic tone, objective facts, and boilerplate.
  - For **faq**, focus on user intent coverage and answer clarity.
  - For **tldr**, focus on key message extraction and brevity.
- **Language:** All feedback/text must be in KOREAN. Status values must be English.
`;

// Helper to clean markdown json blocks if the model ignores instructions
function cleanJsonString(text: string): string {
    let clean = text.trim();
    if (clean.startsWith('```json')) {
        clean = clean.replace(/^```json/, '').replace(/```$/, '');
    } else if (clean.startsWith('```')) {
        clean = clean.replace(/^```/, '').replace(/```$/, '');
    }
    return clean;
}

export const analyzeContent = async (text: string): Promise<AnalysisResult> => {
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: text,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        // IMPORTANT: responseSchema and responseMimeType are NOT allowed with googleSearch tool.
        // We rely on the prompt to enforce JSON structure.
        tools: [{ googleSearch: {} }], 
      }
    });

    if (!response.text) {
        throw new Error("No response generated from AI");
    }

    // 1. Parse JSON Content
    const cleanedText = cleanJsonString(response.text);
    let result: AnalysisResult;
    try {
        result = JSON.parse(cleanedText) as AnalysisResult;
    } catch (e) {
        console.error("JSON Parse Error:", e);
        console.log("Raw Text:", response.text);
        throw new Error("AI analysis response was not valid JSON.");
    }

    // 2. Extract Grounding Metadata (Real URLs)
    // The SDK returns grounding chunks in candidates[0].groundingMetadata
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const webSources = groundingChunks
        .filter((chunk: any) => chunk.web?.uri && chunk.web?.title)
        .map((chunk: any) => ({
            uri: chunk.web.uri,
            title: chunk.web.title
        }));

    // 3. Merge Grounding Data into Result
    if (result.realtime) {
        result.realtime.groundingSources = webSources;

        // Attempt to link fact checks to real sources if possible
        // (This is a heuristic, as specific mapping isn't always 1:1 in the API response)
        result.realtime.factChecks = result.realtime.factChecks.map((check, idx) => ({
            ...check,
            sourceUrl: webSources[idx % webSources.length]?.uri // Distribute sources for reference
        }));
    }

    return result;

  } catch (error) {
    console.error("AI Analysis Failed:", error);
    throw error;
  }
};

